using System.Globalization;
using System.Text;

namespace gen;

/// <summary>
/// Writes one golden-data table.
///
/// Every file is tab-separated with a fixed shape:
///
///     # comment lines describing the columns
///     id  outcome  field  field ...
///
/// A decimal field is its four representation words as unsigned hex,
/// "lo,mid,hi,flags" -- not a rendered number. That is the whole point: comparing
/// rendered numbers cannot detect a wrong scale, a lost trailing zero or a
/// negative zero, and all three are observable differences from .NET.
/// </summary>
public sealed class Writer : IDisposable
{
    readonly StreamWriter _w;
    int _id;

    public Writer(string dir, string name, params string[] columns)
    {
        Directory.CreateDirectory(dir);
        // "\n" explicitly: the files are committed and must not vary by platform.
        _w = new StreamWriter(Path.Combine(dir, name + ".txt")) { NewLine = "\n" };
        _w.WriteLine("# generated by testdata/gen -- do not edit; run `make testdata`");
        _w.WriteLine("# " + string.Join("\t", new[] { "id", "outcome" }.Concat(columns)));
    }

    public static string Bits(decimal d)
    {
        int[] b = decimal.GetBits(d);
        return string.Create(CultureInfo.InvariantCulture,
            $"{(uint)b[0]:x8},{(uint)b[1]:x8},{(uint)b[2]:x8},{(uint)b[3]:x8}");
    }

    /// <summary>Escapes a string field so it can never contain a tab or newline.</summary>
    public static string Str(string s)
    {
        if (s is null) return @"\0";
        var sb = new StringBuilder(s.Length + 2);
        foreach (char c in s)
        {
            switch (c)
            {
                case '\t': sb.Append(@"\t"); break;
                case '\n': sb.Append(@"\n"); break;
                case '\r': sb.Append(@"\r"); break;
                case '\\': sb.Append(@"\\"); break;
                default:
                    // Keep the files ASCII so they are reviewable in a diff; anything
                    // else (the invariant currency sign, non-breaking spaces in some
                    // cultures) goes out as \uXXXX.
                    if (c < 0x20 || c > 0x7e) sb.Append(CultureInfo.InvariantCulture, $"\\u{(int)c:x4}");
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Length == 0 ? @"\e" : sb.ToString();
    }

    /// <summary>Records one case. <paramref name="outcome"/> is "ok" or a failure kind.</summary>
    public void Row(string outcome, params string[] fields)
    {
        _w.Write((++_id).ToString("d6", CultureInfo.InvariantCulture));
        _w.Write('\t');
        _w.Write(outcome);
        foreach (var f in fields) { _w.Write('\t'); _w.Write(f); }
        _w.WriteLine();
    }

    /// <summary>
    /// Runs <paramref name="op"/> and records either its result or the exception it
    /// raised, mapped to the outcome vocabulary the Go side understands.
    /// </summary>
    public void Try(Func<decimal> op, params string[] operands)
    {
        try
        {
            Row("ok", new[] { Bits(op()) }.Concat(operands).ToArray());
        }
        catch (Exception e)
        {
            Row(Kind(e), new[] { "-" }.Concat(operands).ToArray());
        }
    }

    public void TryStr(Func<string> op, params string[] operands)
    {
        try
        {
            Row("ok", new[] { Str(op()) }.Concat(operands).ToArray());
        }
        catch (Exception e)
        {
            Row(Kind(e), new[] { "-" }.Concat(operands).ToArray());
        }
    }

    public static string Kind(Exception e) => e switch
    {
        OverflowException => "overflow",
        DivideByZeroException => "dividebyzero",
        FormatException => "format",
        ArgumentOutOfRangeException => "range",
        ArgumentException => "argument",
        _ => "error:" + e.GetType().Name,
    };

    public int Count => _id;

    public void Dispose() => _w.Dispose();
}
